/* xlaw.c -- ITU-T G.711 u-law and A-law companding.
 *
 * Original implementation, derived from the observed behaviour of the
 * reference program (`-t ul' / `-t al' read and write paths).
 *
 * Naming note: the encoders take an already-rescaled sample.  A 32-bit
 * sox_sample_t is converted by the caller with
 *
 *     lsx_14linear2ulaw(SOX_SAMPLE_TO_SIGNED(14, sample, clips))
 *     lsx_13linear2alaw(SOX_SAMPLE_TO_SIGNED(13, sample, clips))
 *
 * i.e. round-to-nearest down to 14 (u-law) or 13 (A-law) bits.  That macro
 * hands back the low `bits' of the rounded sample as a *non-negative*
 * quantity (there is no int14_t/int13_t to truncate to), so the encoders
 * below re-extend the sign themselves; a caller that passes a properly
 * sign-extended 14/13-bit value gets exactly the same answer.
 */
#include "sox_i.h"

/* Largest magnitude belonging to each chord (segment), in the encoders'
 * respective scales.  The u-law list is offset by one bit relative to the
 * A-law one because u-law adds its bias before the segment lookup. */
static int const ulaw_chord_max[8] = {
  0x3F, 0x7F, 0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF, 0x1FFF
};
static int const alaw_chord_max[8] = {
  0x1F, 0x3F, 0x7F, 0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF
};

#define ULAW_BIAS 33     /* 0x84 expressed in the 14-bit scale */
#define ULAW_CLIP 8159   /* 0x1FFF - ULAW_BIAS + 1 */
#define ALAW_CLIP 3999

static int chord_of(int magnitude, int const *chord_max)
{
  int i;
  for (i = 0; i < 8; ++i)
    if (magnitude <= chord_max[i])
      return i;
  return 8;                    /* over-range: caller emits the peak code */
}

/* Re-interpret the low `bits' of v as a two's complement quantity. */
static int sign_extend(int v, int bits)
{
  int const half = 1 << (bits - 1);
  return (v >= half && v < 2 * half) ? v - 2 * half : v;
}

unsigned char lsx_14linear2ulaw(int16_t pcm_val)
{
  int magnitude = sign_extend(pcm_val, 14), chord;
  unsigned mask, code;

  if (magnitude < 0) {
    magnitude = -magnitude;
    mask = 0x7F;               /* negative: sign bit ends up clear */
  } else
    mask = 0xFF;

  if (magnitude > ULAW_CLIP)
    magnitude = ULAW_CLIP;
  magnitude += ULAW_BIAS;

  chord = chord_of(magnitude, ulaw_chord_max);
  if (chord >= 8)
    return (unsigned char)(0x7F ^ mask);

  code = ((unsigned)chord << 4) | ((magnitude >> (chord + 1)) & 0xF);
  return (unsigned char)(code ^ mask);
}

unsigned char lsx_13linear2alaw(int16_t pcm_val)
{
  int magnitude = sign_extend(pcm_val, 13), chord;
  unsigned mask, code;

  if (magnitude >= 0)
    mask = 0xD5;               /* 0x55 with the sign bit set */
  else {
    mask = 0x55;
    magnitude = -magnitude - 1;
  }

  if (magnitude > ALAW_CLIP)
    magnitude = ALAW_CLIP;

  chord = chord_of(magnitude, alaw_chord_max);
  if (chord >= 8)
    return (unsigned char)(0x7F ^ mask);

  /* The two lowest chords share a step size, hence the fixed shift. */
  code = ((unsigned)chord << 4) |
         ((magnitude >> (chord < 2 ? 1 : chord)) & 0xF);
  return (unsigned char)(code ^ mask);
}

int16_t lsx_ulaw2linear16(unsigned char u_val)
{
  unsigned u = (unsigned)(unsigned char)~u_val;
  int magnitude = (int)(((u & 0x0F) << 3) + 0x84) << ((u & 0x70) >> 4);

  return (int16_t)((u & 0x80) ? 0x84 - magnitude : magnitude - 0x84);
}

int16_t lsx_alaw2linear16(unsigned char a_val)
{
  unsigned a = (unsigned)a_val ^ 0x55;
  unsigned chord = (a & 0x70) >> 4;
  int magnitude = (int)((a & 0x0F) << 4);

  if (!chord)
    magnitude += 8;            /* the two lowest chords are co-linear */
  else
    magnitude = (magnitude + 0x108) << (chord - 1);

  return (int16_t)((a & 0x80) ? magnitude : -magnitude);
}

