 * the conversion with a table lookup gets the same answer as one that decodes
 * to sox_sample_t and re-encodes.  Rounding a v << 16 sample to n bits is
 * (v + 2^(15-n)) >> (16-n). */
static void inittabs(void)
{
  int i;

  if (lsx_ulaw_to_alaw_table)
