#include "sox_i.h"
#include <assert.h>

/* stubs for the helpers xlaw.c uses */
sox_globals_t sox_globals;
void *lsx_malloc(size_t n) { void *p = malloc(n); assert(p); return p; }
void *lsx_realloc(void *p, size_t n) { p = realloc(p, n); assert(p); return p; }

static int read_ints(char const *path, int *out, int n)
{
  FILE *f = fopen(path, "r"); int i, v;
  if (!f) { perror(path); exit(1); }
  for (i = 0; i < n; ++i) { if (fscanf(f, "%d", &v) != 1) { fprintf(stderr,"short %s at %d\n",path,i); exit(1);} out[i]=v; }
  fclose(f); return n;
}

/* the project's own macro, exactly as another module would invoke it */
sox_sample_t lsx_macro_temp_sample; double lsx_macro_temp_double;

static int ref_ul_dec[256], ref_al_dec[256];
static int ref_sw_ul[65536], ref_sw_al[65536];
static int ref_u2a[256], ref_a2u[256];

int main(void)
{
  int i, bad = 0, n;
  uint64_t clips = 0;

  read_ints("/tmp/ul_dec.txt", ref_ul_dec, 256);
  read_ints("/tmp/al_dec.txt", ref_al_dec, 256);
  read_ints("/tmp/sw_ul.txt", ref_sw_ul, 65536);
  read_ints("/tmp/sw_al.txt", ref_sw_al, 65536);
  read_ints("/tmp/ul2al.txt", ref_u2a, 256);
  read_ints("/tmp/al2ul.txt", ref_a2u, 256);

  /* 1. decode tables */
  for (i = 0, n = 0; i < 256; ++i) {
    if (lsx_ulaw2linear_table[i] != (sox_sample_t)ref_ul_dec[i]) { ++n;
      printf("ul tab %d: got %d want %d\n", i, lsx_ulaw2linear_table[i], ref_ul_dec[i]); }
    if (lsx_alaw2linear_table[i] != (sox_sample_t)ref_al_dec[i]) { ++n;
      printf("al tab %d: got %d want %d\n", i, lsx_alaw2linear_table[i], ref_al_dec[i]); }
  }
  printf("decode tables: %d/512 ok\n", 512 - n); bad += n;

  /* 2. decode functions agree with the tables */
  for (i = 0, n = 0; i < 256; ++i) {
    if (SOX_SIGNED_16BIT_TO_SAMPLE(lsx_ulaw2linear16(i), clips) != lsx_ulaw2linear_table[i]) { ++n;
      printf("ulaw2linear16(%d)=%d\n", i, lsx_ulaw2linear16(i)); }
    if (SOX_SIGNED_16BIT_TO_SAMPLE(lsx_alaw2linear16(i), clips) != lsx_alaw2linear_table[i]) { ++n;
      printf("alaw2linear16(%d)=%d\n", i, lsx_alaw2linear16(i)); }
  }
  printf("decode fns:    %d/512 ok\n", 512 - n); bad += n;

  /* 3. the full 65536-entry encode sweep, driven exactly the way a raw
   *    writer would: 16-bit input -> sox_sample_t -> SOX_SAMPLE_TO_SIGNED. */
  n = 0;
  for (i = -32768; i < 32768; ++i) {
    sox_sample_t samp = SOX_SIGNED_16BIT_TO_SAMPLE((int16_t)i, clips);
    unsigned char u = lsx_14linear2ulaw(SOX_SAMPLE_TO_SIGNED(14, samp, clips));
    unsigned char a = lsx_13linear2alaw(SOX_SAMPLE_TO_SIGNED(13, samp, clips));
    if (u != ref_sw_ul[i + 32768]) { if (n < 8) printf("ul %d: %u want %d\n", i, u, ref_sw_ul[i+32768]); ++n; }
    if (a != ref_sw_al[i + 32768]) { if (n < 8) printf("al %d: %u want %d\n", i, a, ref_sw_al[i+32768]); ++n; }
  }
  printf("encode sweep:  %d/131072 ok\n", 131072 - n); bad += n;

  /* 3b. same sweep but passing properly sign-extended 14/13-bit values */
  n = 0;
  for (i = -32768; i < 32768; ++i) {
    sox_sample_t samp = SOX_SIGNED_16BIT_TO_SAMPLE((int16_t)i, clips);
    int u14 = SOX_SAMPLE_TO_SIGNED(14, samp, clips);
    int a13 = SOX_SAMPLE_TO_SIGNED(13, samp, clips);
    if (u14 >= 8192) u14 -= 16384;
    if (a13 >= 4096) a13 -= 8192;
    if (lsx_14linear2ulaw((int16_t)u14) != ref_sw_ul[i + 32768]) ++n;
    if (lsx_13linear2alaw((int16_t)a13) != ref_sw_al[i + 32768]) ++n;
  }
  printf("encode sweep (sign-extended args): %d/131072 ok\n", 131072 - n); bad += n;

  /* 4. cross tables */
  lsx_ulaw_inittabs(); lsx_alaw_inittabs(); lsx_ulaw_inittabs();
  for (i = 0, n = 0; i < 256; ++i) {
    if (lsx_ulaw_to_alaw_table[i] != ref_u2a[i]) { ++n;
      printf("u2a %d: got %u want %d\n", i, lsx_ulaw_to_alaw_table[i], ref_u2a[i]); }
    if (lsx_alaw_to_ulaw_table[i] != ref_a2u[i]) { ++n;
      printf("a2u %d: got %u want %d\n", i, lsx_alaw_to_ulaw_table[i], ref_a2u[i]); }
  }
  printf("cross tables:  %d/512 ok\n", 512 - n); bad += n;

  printf(bad ? "FAIL (%d)\n" : "ALL OK (%d)\n", bad);
  return bad != 0;
}
